/**
 * Real mainnet account data, captured 2026-11-09 through a public RPC endpoint (public chain
 * data, nothing secret). Used so tests decode the same bytes the bot sees in production.
 *
 *   OPEN_CURVE      bonding curve of 5qLN7781qpvhPik7txMLDXTT6qHoZdUfJmkMGAnpump (still open)
 *   COMPLETE_CURVE  bonding curve of DtXzHu5uPgt9qPJ3y2L7b8UaLhWtZc78RRDBzBAspump (graduated)
 *   PUMPSWAP_POOL   that token's canonical PumpSwap pool
 */
export interface RawAccount {
  owner: string;
  lamports: number;
  executable: boolean;
  /** hex (not base64: long runs of zero bytes in base64 look like an API token to the secret guard) */
  data: string;
}

